// component 0: bounded work queue shard 0
template<class T> struct Shard0 {
  std::mutex m; std::deque<T> q; std::condition_variable cv;
  void push(T v){ std::lock_guard<std::mutex> g(m); q.push_back(std::move(v)); cv.notify_one(); }
  bool pop(T& out){ std::unique_lock<std::mutex> g(m); if(q.empty()) return false; out=std::move(q.front()); q.pop_front(); return true; }
};
